-------------------------------------------------------------------------------
-- Description:
-- I2C master / slave with CSR access over the SBI bus :
-- * I2C_registers (generated by regtool from hdl/csr/I2C.hjson) : data
--   (TX / RX FIFO), cmd (master command FIFO), cfg, prescaler, status
-- * i2c_core : I2C protocol, reset while cfg.enable = 0
-- Simulation only : dump of the CMD / TX / RX FIFO traffic in text files.
-------------------------------------------------------------------------------
-- Copyright (c) 2026
-------------------------------------------------------------------------------
-- Revisions  :
-- Date        Version  Author   Description
-- 2026-10-22  1.0      mrosiere Created
-------------------------------------------------------------------------------

library IEEE;
use     IEEE.STD_LOGIC_1164.ALL;
use     IEEE.numeric_std.ALL;
use     ieee.std_logic_textio.all;
use     std.textio.all;

library asylum;
use     asylum.sbi_pkg.all;
use     asylum.i2c_pkg.all;
use     asylum.I2C_csr_pkg.all;

entity sbi_I2C is
  generic(
    NAME                  : string  := "";
    USER_DEFINE_PRESCALER : boolean := true;                         -- Prescaler register writable by software
    PRESCALER_RATIO       : std_logic_vector(8-1 downto 0) := x"7C"; -- Default value for prescaler ratio (100 kHz with a 50 MHz clock)
    MASTER_ENABLE         : boolean := true;                         -- Implement the master (and the cmd register)
    SLAVE_ENABLE          : boolean := true;                         -- Implement the slave
    DEPTH_CMD             : natural := 0;
    DEPTH_TX              : natural := 0;
    DEPTH_RX              : natural := 0;

    FILENAME_CMD          : string  := "dump_i2c_cmd.txt";
    FILENAME_TX           : string  := "dump_i2c_tx.txt";
    FILENAME_RX           : string  := "dump_i2c_rx.txt"
    );
  port   (
    clk_i            : in  std_logic;
    arst_b_i         : in  std_logic; -- asynchronous reset

    -- Bus
    sbi_ini_i        : in  sbi_ini_t;
    sbi_tgt_o        : out sbi_tgt_t;

    -- I2C Interface (open drain : xx_o is always 0, xx_oe_o = 1 pulls the line low)
    scl_i            : in  std_logic;
    scl_o            : out std_logic;
    scl_oe_o         : out std_logic;
    sda_i            : in  std_logic;
    sda_o            : out std_logic;
    sda_oe_o         : out std_logic
    );

end entity sbi_I2C;

architecture rtl of sbi_I2C is

-- synthesis translate_off
  file     file_cmd               : text open write_mode is FILENAME_CMD;
  file     file_tx                : text open write_mode is FILENAME_TX;
  file     file_rx                : text open write_mode is FILENAME_RX;
  signal   dump_init              : std_logic := '0';
-- synthesis translate_on

  signal   sw2hw                  : I2C_sw2hw_t;
  signal   hw2sw                  : I2C_hw2sw_t;

  alias    tx_tvalid              : std_logic        is sw2hw.data.valid;
  alias    tx_tready              : std_logic        is hw2sw.data.ready;
  alias    tx_tdata               : std_logic_vector is sw2hw.data.value;

  alias    rx_tvalid              : std_logic        is hw2sw.data.valid;
  alias    rx_tready              : std_logic        is sw2hw.data.ready;
  alias    rx_tdata               : std_logic_vector is hw2sw.data.value;

  alias    cmd_tvalid             : std_logic        is sw2hw.cmd.valid;
  alias    cmd_tready             : std_logic        is hw2sw.cmd.ready;

  -- The core is held in reset while cfg.enable = 0
  alias    i2c_core_arst_b        : std_logic        is sw2hw.cfg.enable(0);

begin  -- architecture rtl

  -----------------------------------------------------------------------------
  -- CSR Instance
  -----------------------------------------------------------------------------
  ins_csr : I2C_registers
  generic map
  ( MODULE_NAME           => NAME
   ,USER_DEFINE_PRESCALER => USER_DEFINE_PRESCALER
   ,PRESCALER_RATIO       => PRESCALER_RATIO
   ,MASTER_ENABLE         => MASTER_ENABLE
   ,DEPTH_TX              => DEPTH_TX
   ,DEPTH_RX              => DEPTH_RX
   ,DEPTH_CMD             => DEPTH_CMD
    )
  port map
  (
    clk_i     => clk_i
   ,arst_b_i  => arst_b_i
   ,sbi_ini_i => sbi_ini_i
   ,sbi_tgt_o => sbi_tgt_o
   ,sw2hw_o   => sw2hw
   ,hw2sw_i   => hw2sw
  );

  -----------------------------------------------------------------------------
  -- I2C Core
  -----------------------------------------------------------------------------
  ins_i2c_core : i2c_core
    generic map
    ( PRESCALER_WIDTH       => 8
     ,MASTER_ENABLE         => MASTER_ENABLE
     ,SLAVE_ENABLE          => SLAVE_ENABLE
     )
    port map
    ( clk_i                 => clk_i
     ,arst_b_i              => i2c_core_arst_b
     ,tx_tvalid_i           => sw2hw.data.valid
     ,tx_tready_o           => hw2sw.data.ready
     ,tx_tdata_i            => sw2hw.data.value
     ,rx_tvalid_o           => hw2sw.data.valid
     ,rx_tready_i           => sw2hw.data.ready
     ,rx_tdata_o            => hw2sw.data.value
     ,cmd_tvalid_i          => sw2hw.cmd.valid
     ,cmd_tready_o          => hw2sw.cmd.ready
     ,cmd_start_i           => sw2hw.cmd.start(0)
     ,cmd_stop_i            => sw2hw.cmd.stop(0)
     ,cmd_op_i              => sw2hw.cmd.op
     ,cfg_prescaler_ratio_i => sw2hw.prescaler.ratio
     ,cfg_slave_addr_i      => sw2hw.cfg.slave_addr
     ,sts_busy_o            => hw2sw.status.busy(0)
     ,sts_nack_o            => hw2sw.status.nack(0)
     ,sts_bus_busy_o        => hw2sw.status.bus_busy(0)
     ,sts_slave_addressed_o => hw2sw.status.slave_addressed(0)
     ,sts_slave_read_o      => hw2sw.status.slave_read(0)
     ,scl_i                 => scl_i
     ,scl_o                 => scl_o
     ,scl_oe_o              => scl_oe_o
     ,sda_i                 => sda_i
     ,sda_o                 => sda_o
     ,sda_oe_o              => sda_oe_o
    );

  -----------------------------------------------------------------------------
  -- Status
  -----------------------------------------------------------------------------
  hw2sw.status.we          <= '1';
  hw2sw.status.rx_empty(0) <= sw2hw.data.hw2sw_empty;

  -----------------------------------------------------------------------------
  -- Debug
  -----------------------------------------------------------------------------
-- synthesis translate_off
  process (clk_i) is
    variable line_buffer : line;

  begin  -- process

    if rising_edge(clk_i)
    then
      if dump_init = '0'
      then
        dump_init <= '1';

        write(line_buffer, string'("TX format: <binary> - 0x<hex> - <char>"));
        writeline(file_tx, line_buffer);

        write(line_buffer, string'("RX format: <binary> - 0x<hex> - <char>"));
        writeline(file_rx, line_buffer);

        write(line_buffer, string'("CMD format: start - stop - op <binary>"));
        writeline(file_cmd, line_buffer);
      end if;

      if (tx_tvalid and tx_tready)
      then
        write    (line_buffer, tx_tdata);
        write    (line_buffer, string'(" - 0x"));
        write    (line_buffer, to_hstring(tx_tdata));
        write    (line_buffer, string'(" - "));
        write    (line_buffer, character'val(to_integer(unsigned(tx_tdata))));
        writeline(file_tx, line_buffer);
      end if;

      if (rx_tvalid and rx_tready)
      then
        write    (line_buffer, rx_tdata);
        write    (line_buffer, string'(" - 0x"));
        write    (line_buffer, to_hstring(rx_tdata));
        write    (line_buffer, string'(" - "));
        write    (line_buffer, character'val(to_integer(unsigned(rx_tdata))));
        writeline(file_rx, line_buffer);
      end if;

      if (cmd_tvalid and cmd_tready)
      then
        write    (line_buffer, sw2hw.cmd.start(0));
        write    (line_buffer, string'(" - "));
        write    (line_buffer, sw2hw.cmd.stop(0));
        write    (line_buffer, string'(" - "));
        write    (line_buffer, sw2hw.cmd.op);
        writeline(file_cmd, line_buffer);
      end if;

    end if;
  end process;
-- synthesis translate_on

end architecture rtl;
